// Population by Age — Heatmap, route: jsx
// Source: icelandic-population-by-age-1841-2019
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from populationByAge ----
type PopulationCell = { year: number; age: number; value: number };

const FIRST_YEAR = 1841;
const LAST_YEAR = 2020;
const MAX_AGE = 99;

// Seeded PRNG so the surface is byte identical on every render, reload and machine.
function mulberry32(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const clamp01 = (t: number) => Math.max(0, Math.min(1, t));
const bell = (x: number, center: number, spread: number) =>
  Math.exp(-((x - center) ** 2) / (2 * spread ** 2));

// Mortality falls steadily between 1860 and 2000; 0 is the pre-modern regime, 1 the modern one.
const modernity = (year: number) => clamp01((year - 1860) / 140);

const FIRST_COHORT = FIRST_YEAR - MAX_AGE;

function births(cohort: number, random: () => number): number {
  const trend = 900 * Math.exp(0.0045 * (cohort - FIRST_COHORT));
  const crisis = 1 - 0.5 * bell(cohort, 1881, 4);
  const boom = 1 + 0.9 * bell(cohort, 1955, 9);
  const fertilityDecline = 1 - 0.5 * clamp01((cohort - 1975) / 45);
  return trend * crisis * boom * fertilityDecline * (0.955 + random() * 0.09);
}

// Gompertz old-age term over a flat background, with infant deaths as a separate first-year rate.
function hazard(age: number, year: number): number {
  const modern = modernity(year);
  if (age === 0) return 0.15 * (1 - 0.93 * modern);
  const base = (0.006 + 0.00004 * Math.exp(0.1 * age)) * (1 - 0.62 * modern);
  const famine = year >= 1876 && year <= 1882 ? 1.9 : 1;
  const epidemic = year === 1918 ? 1.7 : 1;
  return base * famine * epidemic;
}

// The crisis-era exodus took working-age adults, hollowing those cohorts for the rest of their lives.
function emigration(age: number, year: number): number {
  if (year < 1876 || year > 1888 || age < 15 || age > 34) return 0;
  return 0.055;
}

function buildSurface(): PopulationCell[] {
  const random = mulberry32(20260813);
  const cells: PopulationCell[] = [];
  for (let cohort = FIRST_COHORT; cohort <= LAST_YEAR; cohort++) {
    let alive = births(cohort, random);
    for (let age = 0; age <= MAX_AGE; age++) {
      const year = cohort + age;
      if (year > LAST_YEAR) break;
      if (year >= FIRST_YEAR) cells.push({ year, age, value: Math.round(alive) });
      alive *= 1 - Math.min(0.95, hazard(age, year) + emigration(age, year));
    }
  }
  return cells;
}

const populationByAge = buildSurface();

const MARGIN = { top: 12, right: 14, bottom: 58, left: 44 };
const LEGEND_WIDTH = 132;
const LEGEND_STOPS = 22;

// Each cohort is a diagonal, so an annotated cohort is a line of constant (year - age).
const COHORT_NOTES = [
  { cohort: 1881, from: 1900, to: 1945, label: '1876 to 1884 crisis cohorts' },
  { cohort: 1955, from: 1975, to: 2015, label: 'postwar boom cohorts' }
];

/** One cell per year and age, plus the extent of the grid those cells fill. */
export type Data = {
  cells: { year: number; age: number; value: number }[];
  firstYear: number;
  lastYear: number;
  maxAge: number;
};

const DEMO: Data = {
  cells: populationByAge,
  firstYear: FIRST_YEAR,
  lastYear: LAST_YEAR,
  maxAge: MAX_AGE
};

export default function PopulationByAge({
  data = DEMO,
  width
}: {
  data?: Data;
  width: number;
}) {
  const { firstYear, lastYear, maxAge } = data;
  const height = Math.round(width * 0.58);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;
  const cellWidth = innerWidth / (lastYear - firstYear + 1);
  const cellHeight = innerHeight / (maxAge + 1);

  const xOf = (year: number) => (year - firstYear) * cellWidth;
  const yOf = (age: number) => (maxAge - age) * cellHeight;

  // Square root ramp: without it the young ages swamp the ramp and the old-age streaks vanish.
  const { color, maxValue } = useMemo(() => {
    const max = d3.max(data.cells, (d) => d.value) ?? 0;
    return {
      color: d3.scaleSequentialSqrt(d3.interpolateViridis).domain([0, max]),
      maxValue: max
    };
  }, [data]);

  const cells = useMemo(
    () =>
      data.cells.map((d) => ({
        key: `${d.year}:${d.age}`,
        x: (d.year - firstYear) * cellWidth,
        y: (maxAge - d.age) * cellHeight,
        fill: color(d.value)
      })),
    [data, firstYear, maxAge, color, cellWidth, cellHeight]
  );

  const xTicks: Tick[] = useMemo(
    () =>
      d3
        .ticks(firstYear, lastYear, Math.max(2, Math.round(innerWidth / 90)))
        .map((year) => ({ value: String(year), offset: (year - firstYear + 0.5) * cellWidth })),
    [firstYear, lastYear, innerWidth, cellWidth]
  );

  const yTicks: Tick[] = useMemo(
    () =>
      d3
        .range(0, maxAge + 1, 20)
        .map((age) => ({ value: String(age), offset: (maxAge - age + 0.5) * cellHeight })),
    [maxAge, cellHeight]
  );

  const legend = useMemo(
    () =>
      d3.range(LEGEND_STOPS).map((i) => {
        const t = i / (LEGEND_STOPS - 1);
        return { t, x: t * (LEGEND_WIDTH - LEGEND_WIDTH / LEGEND_STOPS), fill: color(maxValue * t * t) };
      }),
    [color, maxValue]
  );

  if (width === 0) return null;

  const showAnnotations = width >= 520;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={
        'Lexis heatmap of population by year and age. Year runs left to right from 1841 to 2020, ' +
        'age runs bottom to top from 0 to 99, and cell color encodes how many people were that age ' +
        'in that year. Birth cohorts read as diagonal streaks: a dark streak for the cohorts born ' +
        'during the 1876 to 1884 crisis, a bright band for the postwar boom cohorts. Synthetic data ' +
        'from a seeded generator, not Statistics Iceland or any real population registry.'
      }
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <g>
          {cells.map((cell) => (
            <rect
              key={cell.key}
              x={cell.x}
              y={cell.y}
              width={cellWidth + 0.5}
              height={cellHeight + 0.5}
              fill={cell.fill}
            />
          ))}
        </g>
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />

        {showAnnotations &&
          COHORT_NOTES.map((note) => (
            <g key={note.cohort}>
              <line
                x1={xOf(note.from)}
                y1={yOf(note.from - note.cohort)}
                x2={xOf(note.to)}
                y2={yOf(note.to - note.cohort)}
                stroke="#fff"
                strokeOpacity={0.55}
                strokeDasharray="3 3"
              />
              <text
                x={xOf((note.from + note.to) / 2)}
                y={yOf((note.from + note.to) / 2 - note.cohort) - 7}
                textAnchor="middle"
                fontSize={11}
                fill="#fff"
                stroke="rgba(0,0,0,0.65)"
                strokeWidth={3}
                paintOrder="stroke"
              >
                {note.label}
              </text>
            </g>
          ))}

        {width >= 420 && (
          <g transform="translate(8,8)">
            <text y={9} fontSize={10} fill="var(--text)">
              People aged a in year y
            </text>
            {legend.map((stop) => (
              <rect
                key={stop.t}
                x={stop.x}
                y={16}
                width={LEGEND_WIDTH / LEGEND_STOPS + 0.5}
                height={8}
                fill={stop.fill}
              />
            ))}
            <text y={37} fontSize={10} fill="var(--muted)">
              0
            </text>
            <text x={LEGEND_WIDTH} y={37} textAnchor="end" fontSize={10} fill="var(--muted)">
              {d3.format(',')(Math.round(maxValue / 100) * 100)}
            </text>
          </g>
        )}

        <text x={-MARGIN.left + 2} y={-2} fontSize={11} fill="var(--muted)">
          Age ↑
        </text>
        <text x={innerWidth} y={innerHeight + 32} textAnchor="end" fontSize={11} fill="var(--muted)">
          Year →
        </text>
        <text x={0} y={innerHeight + 48} fontSize={11} fill="var(--muted)">
          Synthetic data from a seeded generator, not Statistics Iceland or any real population
          registry.
        </text>
      </g>
    </svg>
  );
}
